SET search_path=model_lab,pg_catalog;
SELECT jsonb_build_object('version',1,'kind','database-design-lab-observations','scope','Disposable synthetic PostgreSQL lab, not Supabase integration or a deployed migration','serverVersion',current_setting('server_version'),'checks',(SELECT jsonb_agg(jsonb_build_object('name',name,'passed',passed) ORDER BY name) FROM check_results),'complete',(SELECT bool_and(passed) FROM check_results),'searchDocuments',(SELECT count(*) FROM search_documents),'sessions',(SELECT count(*) FROM sessions),'realStudentRecordsRead',0,'existingDatabasesChanged',false);
